INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 14, 'theory', 'Quiz: modules, Rust, and observability');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 0, 'What does the pair of numbers on a device file in /dev mean?', '["The size of the device in megabytes", "The owner and the group", "The major number picks the driver, the minor number picks the particular device instance", "The driver and kernel version"]', 2, 'The files themselves are created by the udev service from events sent by the kernel.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 1, 'How is modprobe better than insmod?', '["It handles dependencies and loads the needed modules by itself", "It can forcibly unload any module", "It works without root rights", "It speeds up the module"]', 0, 'The dependency file is built ahead of time, so modprobe first loads what the module depends on.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 2, 'What is the status of Rust in the Linux kernel starting with version 7.0?', '["Rust has completely replaced C", "Rust support was removed", "Rust is allowed only for userspace utilities", "The experimental label was lifted: Rust is an official part of the kernel, and there are already real drivers in it"]', 3, 'Support arrived in 6.1; in 6.18 the Binder and Tyr drivers in Rust were merged.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 3, 'The load average is 12 on a machine with 4 cores. How should you read that?', '["The processor is 12 percent busy", "The queue is about three times longer than capacity, but the cause (CPU, disk) must be looked for in vmstat and PSI", "The machine has 12 cores", "It is normal for any server"]', 1, 'Load also counts waiting for the disk. The PSI pressure metrics directly measure stalls.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 4, 'Why is it safe to load an eBPF program into a running kernel?', '["The verifier proves that it terminates and does not go outside memory bounds", "It runs only in user mode with no access to the kernel", "An antivirus checks it", "It runs in a separate virtual machine"]', 0, 'Thanks to this, bpftrace, XDP, and sched_ext can be attached on the fly.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 5, 'What does the load average show?', '["The percentage of CPU busy time", "The processor temperature", "The average number of tasks ready to run or waiting for disk, over 1, 5, and 15 minutes", "The number of running processes"]', 2, 'A load above the number of cores signals a queue. But the cause may be the disk rather than the processor.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 6, 'How do you change a kernel parameter without a reboot?', '["Rebuild the kernel", "Write the value to a file under /proc/sys or run sysctl", "Edit the bootloader and reboot", "It is impossible"]', 1, 'Many parameters are live: writing to the file changes kernel behavior immediately. To make the change survive a reboot, it is written to the configuration.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 14, 7, 'How is modprobe more convenient than insmod?', '["It loads only modules signed by the vendor", "It unloads all modules", "It compiles the module before loading", "It finds the module by name and loads the dependencies it needs by itself"]', 3, 'insmod loads one specified file. modprobe reads the module dependency map.');
